/**
 * Seasonal plan-idea bank for the title placeholder. A big curated list of
 * hangout ideas tagged by season; the composer cycles through the ones that
 * fit the current time of year (so in October you see "apple picking" and
 * "costume party", in July "beach day" and "rooftop drinks"). Evergreen ideas
 * (tagged "any") show all year.
 *
 * The IDEAS array is generated by the plan-idea-bank workflow and baked in
 * here so it is instant and offline. `s` is the set of seasons an idea fits;
 * "any" means every season.
 */

export type Season = 'spring' | 'summer' | 'fall' | 'winter'
export interface Idea {
  t: string
  s: (Season | 'any')[]
}

export function seasonForDate(d = new Date()): Season {
  const m = d.getMonth() // 0-11, Northern Hemisphere
  if (m >= 2 && m <= 4) return 'spring'
  if (m >= 5 && m <= 7) return 'summer'
  if (m >= 8 && m <= 10) return 'fall'
  return 'winter'
}

function shuffle<T>(arr: T[]): T[] {
  const a = [...arr]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

/**
 * Ideas to cycle in the placeholder right now: this season's ideas first (so it
 * feels timely the instant the page loads), then evergreen ones for variety.
 */
export function seasonalPlaceholders(d = new Date()): string[] {
  const season = seasonForDate(d)
  const seasonal: string[] = []
  const evergreen: string[] = []
  for (const idea of IDEAS) {
    if (idea.s.includes(season)) seasonal.push(idea.t)
    else if (idea.s.includes('any')) evergreen.push(idea.t)
  }
  return [...shuffle(seasonal), ...shuffle(evergreen)]
}

